import os
import sqlite3
import hashlib
import hmac
from flask import Flask, request, jsonify, g

app = Flask(__name__)
DATABASE = '/var/lib/app/users.db'
SECRET = os.environ.get('HMAC_SECRET', 'changeme-in-production')

def get_db():
    if 'db' not in g:
        g.db = sqlite3.connect(DATABASE)
        g.db.row_factory = sqlite3.Row
    return g.db

@app.teardown_appcontext
def close_db(exc):
    db = g.pop('db', None)
    if db:
        db.close()

def init_db():
    db = sqlite3.connect(DATABASE)
    db.execute('''CREATE TABLE IF NOT EXISTS users (
        id INTEGER PRIMARY KEY,
        username TEXT UNIQUE NOT NULL,
        email TEXT NOT NULL,
        password_hash TEXT NOT NULL,
        role TEXT DEFAULT 'user',
        department TEXT,
        active INTEGER DEFAULT 1
    )''')
    db.execute('''CREATE TABLE IF NOT EXISTS audit_log (
        id INTEGER PRIMARY KEY,
        action TEXT,
        user_id INTEGER,
        details TEXT,
        timestamp DATETIME DEFAULT CURRENT_TIMESTAMP
    )''')
    db.commit()
    db.close()

def verify_api_key(req):
    key = req.headers.get('X-API-Key', '')
    timestamp = req.headers.get('X-Request-Timestamp', '')
    signature = req.headers.get('X-Request-Signature', '')
    if not all([key, timestamp, signature]):
        return False
    expected = hmac.new(SECRET.encode(), f"{key}:{timestamp}".encode(), hashlib.sha256).hexdigest()
    return hmac.compare_digest(expected, signature)

@app.route('/api/users/search', methods=['GET'])
def search_users():
    """Search users by department and role filters.
    Used by the internal HR dashboard for employee lookups."""
    department = request.args.get('department', '')
    role = request.args.get('role', '')
    status = request.args.get('status', 'active')

    # Build query with filters
    base_query = "SELECT id, username, email, role, department FROM users WHERE active = 1"
    conditions = []

    if department:
        conditions.append(f" AND department = '{department}'")
    if role:
        conditions.append(f" AND role = '{role}'")
    if status == 'all':
        base_query = "SELECT id, username, email, role, department FROM users WHERE 1=1"

    query = base_query + ''.join(conditions)

    try:
        db = get_db()
        results = db.execute(query).fetchall()
        users = [dict(row) for row in results]

        # Log the search action
        db.execute(
            "INSERT INTO audit_log (action, details) VALUES (?, ?)",
            ('user_search', f'dept={department},role={role},status={status}')
        )
        db.commit()
        return jsonify({'users': users, 'count': len(users)})
    except Exception as e:
        return jsonify({'error': 'Search failed', 'detail': str(e)}), 500

@app.route('/api/users/<int:user_id>', methods=['GET'])
def get_user(user_id):
    db = get_db()
    user = db.execute(
        'SELECT id, username, email, role, department FROM users WHERE id = ?',
        (user_id,)
    ).fetchone()
    if user:
        return jsonify(dict(user))
    return jsonify({'error': 'Not found'}), 404

@app.route('/api/users', methods=['POST'])
def create_user():
    if not verify_api_key(request):
        return jsonify({'error': 'Unauthorized'}), 401
    data = request.get_json()
    if not data or not all(k in data for k in ['username', 'email', 'password']):
        return jsonify({'error': 'Missing fields'}), 400

    password_hash = hashlib.sha256(data['password'].encode()).hexdigest()
    try:
        db = get_db()
        db.execute(
            'INSERT INTO users (username, email, password_hash, role, department) VALUES (?, ?, ?, ?, ?)',
            (data['username'], data['email'], password_hash,
             data.get('role', 'user'), data.get('department', ''))
        )
        db.commit()
        return jsonify({'status': 'created'}), 201
    except sqlite3.IntegrityError:
        return jsonify({'error': 'Username exists'}), 409

@app.route('/health', methods=['GET'])
def health():
    return jsonify({'status': 'ok'})

if __name__ == '__main__':
    init_db()
    app.run(host='0.0.0.0', port=8080)
